<div class="container-xl"><div class="page-header"><div><div class="page-pretitle">Pembelajaran</div><h2 class="page-title">Analitik English RPG</h2></div></div><div class="row g-3 my-3"><?php foreach([['Pemain',$stats['players'],'ti-users'],['Jawaban',$stats['attempts'],'ti-swords'],['Chapter selesai',$stats['completed'],'ti-trophy'],['Data mastery',$stats['words'],'ti-book']] as $s): ?><div class="col-md-3"><div class="card"><div class="card-body"><i class="ti <?= $s[2]; ?> fs-1 text-primary"></i><h2><?= $s[1]; ?></h2><span><?= $s[0]; ?></span></div></div></div><?php endforeach; ?></div><div class="row g-3"><div class="col-lg-7"><div class="card"><div class="card-header"><h3 class="card-title">Progres Pemain</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Pemain</th><th>Class</th><th>Chapter</th><th>Benar</th><th>Salah</th><th>Streak</th></tr></thead><tbody><?php foreach($players as $p): ?><tr><td><?= html_escape($p['avatar'].' '.($p['hero_name']?:$p['full_name'])); ?></td><td><?= html_escape(str_replace('_',' ',$p['class_code'])); ?></td><td><?= (int)$p['chapters']; ?></td><td><?= (int)$p['total_correct']; ?></td><td><?= (int)$p['total_wrong']; ?></td><td><?= (int)$p['streak_days']; ?> hari</td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="col-lg-5"><div class="card"><div class="card-header"><h3 class="card-title">Kosakata Tersulit</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Kata</th><th>Mastery</th><th>Salah</th></tr></thead><tbody><?php foreach($hard_words as $w): ?><tr><td><b><?= html_escape($w['word']); ?></b><small class="d-block text-secondary"><?= html_escape($w['meaning']); ?></small></td><td><?= round($w['mastery']); ?>%</td><td><?= (int)$w['wrong']; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></div>
